html {
  font-size: 100%;        /* 16px by default, and respects the user's setting */
}

h1 {
  font-size: 2rem;         /* 32px */
}

p {
  font-size: 1.125rem;     /* 18px */
  max-width: 45ch;         /* about 45 characters per line */
}

.card {
  font-size: 0.875rem;     /* 14px */
  padding: 1.5em;          /* 1.5 x 14px = 21px, scales with the card's text */
  border: 1px solid #cbd5e1;
}

/* Never wider than 40rem, never wider than the viewport minus a margin */
body {
  width: min(100% - 2rem, 40rem);
  margin: 0 auto;
}

/* Fluid heading: at least 1.5rem, at most 3rem, 2.5vw-based in between */
h1 {
  font-size: clamp(1.5rem, 1rem + 2.5vw, 3rem);
}

.card {
  padding: calc(0.5rem + 1vw);
  border: 1px solid #cbd5e1;
}
